SET LOCAL ROLE scrbrd_app;
DO $setup$ DECLARE ids jsonb := current_setting('demo.ids')::jsonb; m uuid := nullif(current_setting('demo.m', true), '')::uuid;
        r record; d uuid; n integer; v uuid; t uuid;
BEGIN
  -- Kearsney's own ground, added by its director of sport (facility.manage).
  PERFORM app_session_begin((ids->>'dos.kea@example.invalid')::uuid, 'demo-season', NULL, NULL);
  INSERT INTO ground (id, school_id, name, surface, end_a_name, end_b_name)
  VALUES ('de5e0000-0000-4000-a000-000000000a01', '33333333-3333-3333-3333-333333333333', 'Kearsney Main', 'turf', 'Chapel End', 'Pavilion End');

  -- Kearsney's 1XI into the KZN Schools T20 League: the league's administrator
  -- invites, Kearsney's director of sport accepts (db/67), Division 1.
  PERFORM app_session_begin((ids->>'league@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT x.ok, x.reason, x.entrant_id AS id INTO r FROM competition_entrant_invite('99999999-0000-0000-0000-000000000001', '33333333-3333-3333-3333-333333333333', '1XI', 'Kearsney 1st XI') x;
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The league could not invite Kearsney''s 1XI: %. Nothing was changed.', r.reason; END IF;
  v := r.id;
  PERFORM app_session_begin((ids->>'dos.kea@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM competition_entrant_respond(v, true);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'Kearsney could not accept the league''s invitation: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'league@example.invalid')::uuid, 'demo-season', NULL, NULL);
  UPDATE competition_entrant SET division_id = 'd1710000-0000-0000-0000-000000000001' WHERE id = v;

  -- The league's points, confirmed from its rules and published by its
  -- administrator (POST /api/competitions/:id/playing-conditions, …/values,
  -- …/publish). A version takes effect from tomorrow (db/61: never back-dated),
  -- so the fixtures already played take it by the designed path for a played
  -- match: the administrator re-fixes each one's table figures from it, with a
  -- reason (match_conditions_refix_table(), db/69), before confirming its result.
  -- The table is then computed from the results rather than typed.
  SELECT x.ok, x.reason, x.set_id AS id INTO r FROM condition_set_draft('99999999-0000-0000-0000-000000000001', 'KZN Schools T20 League 2026 (demo)', sa_today() + 1) x;
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The league could not draft its playing conditions: %. Nothing was changed.', r.reason; END IF;
  t := r.id;
  SELECT * INTO r FROM condition_value_enter(t, 'points.win', '', '4'::jsonb, 'confirmed', 'League rules 2026 (demo)', '4.1', date '2026-09-15', NULL);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The league could not enter points.win: %. Nothing was changed.', r.reason; END IF;
  SELECT * INTO r FROM condition_value_enter(t, 'points.loss', '', '0'::jsonb, 'confirmed', 'League rules 2026 (demo)', '4.2', date '2026-09-15', NULL);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The league could not enter points.loss: %. Nothing was changed.', r.reason; END IF;
  SELECT * INTO r FROM condition_value_enter(t, 'points.tie', '', '2'::jsonb, 'confirmed', 'League rules 2026 (demo)', '4.3', date '2026-09-15', NULL);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The league could not enter points.tie: %. Nothing was changed.', r.reason; END IF;
  SELECT * INTO r FROM condition_value_enter(t, 'points.draw', '', '2'::jsonb, 'confirmed', 'League rules 2026 (demo)', '4.4', date '2026-09-15', NULL);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The league could not enter points.draw: %. Nothing was changed.', r.reason; END IF;
  SELECT * INTO r FROM condition_value_enter(t, 'points.no_result', '', '2'::jsonb, 'confirmed', 'League rules 2026 (demo)', '4.5', date '2026-09-15', NULL);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The league could not enter points.no_result: %. Nothing was changed.', r.reason; END IF;
  SELECT * INTO r FROM condition_value_enter(t, 'points.abandoned', '', '2'::jsonb, 'confirmed', 'League rules 2026 (demo)', '4.6', date '2026-09-15', NULL);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The league could not enter points.abandoned: %. Nothing was changed.', r.reason; END IF;
  SELECT * INTO r FROM condition_value_enter(t, 'nrr.method', '', '"standard"'::jsonb, 'confirmed', 'League rules 2026 (demo)', '4.7', date '2026-09-15', NULL);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The league could not enter nrr.method: %. Nothing was changed.', r.reason; END IF;
  SELECT * INTO r FROM condition_set_publish(t);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The league could not publish its playing conditions: %. Nothing was changed.', r.reason; END IF;

  -- Kearsney's minibus, as POST /api/vehicles adds it (Westville's came with the cast).
  PERFORM app_session_begin((ids->>'transport.kea@example.invalid')::uuid, 'demo-season', NULL, NULL);
  INSERT INTO vehicle (school_id, registration, description, kind, capacity, condition, next_service_on, active, notes,
                       insurance_expires_on, roadworthy_expires_on)
  VALUES ('33333333-3333-3333-3333-333333333333', 'KEA DEMO 1', 'Demo minibus, 22 seats', 'minibus', 22, 'good', NULL, true, 'Demo season', date '2027-03-31', date '2027-01-31')
  ON CONFLICT DO NOTHING;

  -- The October fixtures this season does not play, rearranged by Westville's director of sport.
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  UPDATE match SET starts_at = timestamptz '2026-11-16T12:30:00Z'
   WHERE school_id = '22222222-2222-2222-2222-222222222222' AND away_school_id = '33333333-3333-3333-3333-333333333333' AND team_code = 'U14B' AND starts_at = timestamptz '2026-10-09T12:30:00Z' AND status = 'scheduled';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Could not rearrange the U14B fixture of 2026-10-09T12:30:00Z (% found). Nothing was changed.', n; END IF;
  UPDATE match SET starts_at = timestamptz '2026-11-17T12:30:00Z'
   WHERE school_id = '22222222-2222-2222-2222-222222222222' AND away_school_id = '33333333-3333-3333-3333-333333333333' AND team_code = 'U15A' AND starts_at = timestamptz '2026-10-12T12:30:00Z' AND status = 'scheduled';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Could not rearrange the U15A fixture of 2026-10-12T12:30:00Z (% found). Nothing was changed.', n; END IF;
  UPDATE match SET starts_at = timestamptz '2026-11-18T12:30:00Z'
   WHERE school_id = '22222222-2222-2222-2222-222222222222' AND away_school_id = '33333333-3333-3333-3333-333333333333' AND team_code = 'U13A' AND starts_at = timestamptz '2026-10-13T12:30:00Z' AND status = 'scheduled';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Could not rearrange the U13A fixture of 2026-10-13T12:30:00Z (% found). Nothing was changed.', n; END IF;
  UPDATE match SET starts_at = timestamptz '2026-11-19T12:30:00Z'
   WHERE school_id = '22222222-2222-2222-2222-222222222222' AND away_school_id = '33333333-3333-3333-3333-333333333333' AND team_code = 'U12A' AND starts_at = timestamptz '2026-10-14T12:30:00Z' AND status = 'scheduled';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Could not rearrange the U12A fixture of 2026-10-14T12:30:00Z (% found). Nothing was changed.', n; END IF;
  UPDATE match SET starts_at = timestamptz '2026-11-20T12:30:00Z'
   WHERE school_id = '22222222-2222-2222-2222-222222222222' AND away_school_id = '33333333-3333-3333-3333-333333333333' AND team_code = 'U15B' AND starts_at = timestamptz '2026-10-16T12:30:00Z' AND status = 'scheduled';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'Could not rearrange the U15B fixture of 2026-10-16T12:30:00Z (% found). Nothing was changed.', n; END IF;

  -- Hilton's two seed fixtures still open in October, against schools not on
  -- SCRBRD, called off by Hilton's office (the fixture route, status abandoned):
  -- one never started, one stopped after sixteen balls and never resumed.
  PERFORM app_session_begin((ids->>'registrar@example.invalid')::uuid, 'demo-season', NULL, NULL);
  UPDATE match SET status = 'abandoned' WHERE id IN ('77777777-0000-0000-0000-000000000002', '77777777-0000-0000-0000-000000000003') AND status = 'scheduled';

  -- Both schools list their matches on the SCRBRD home page (Settings → School).
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM public_listing_set('22222222-2222-2222-2222-222222222222', true);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'Westville could not list its matches: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'dos.kea@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM public_listing_set('33333333-3333-3333-3333-333333333333', true);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'Kearsney could not list its matches: %. Nothing was changed.', r.reason; END IF;
END $setup$;
-- ── 1xi-1007: Westville v Kearsney at Westville Main · KEA 137/9, WES 139/9: WES won ──
RESET ROLE;
SELECT set_config('demo.m', (SELECT id FROM match WHERE school_id = '22222222-2222-2222-2222-222222222222' AND away_school_id = '33333333-3333-3333-3333-333333333333'
   AND team_code = '1XI' AND starts_at = timestamptz '2026-10-07T17:00:00Z')::text, true);
DO $chk$ BEGIN IF nullif(current_setting('demo.m', true), '') IS NULL THEN
  RAISE EXCEPTION 'The demo''s 1XI fixture of 2026-10-07T17:00:00Z is not here. Nothing was changed.'; END IF; END $chk$;
SET LOCAL ROLE scrbrd_app;
DO $before$ DECLARE ids jsonb := current_setting('demo.ids')::jsonb; m uuid := nullif(current_setting('demo.m', true), '')::uuid;
        r record; d uuid; n integer; v uuid; t uuid;
BEGIN

  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  UPDATE match SET competition_id = '99999999-0000-0000-0000-000000000001' WHERE id = m AND competition_id IS DISTINCT FROM '99999999-0000-0000-0000-000000000001';
  IF NOT EXISTS (SELECT 1 FROM match_official o WHERE o.match_id = m AND o.duty = 'umpire' AND NOT o.withdrawn
                   AND (o.person_id = (ids->>'official.wes@example.invalid')::uuid OR 'umpire' IN ('scorer', 'third_umpire', 'referee'))) THEN
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    INSERT INTO match_official (match_id, school_id, duty, person_name, person_id, official_id, panel, appointed_by, appointed_at)
