 CROSS JOIN LATERAL (SELECT replace(replace(replace((e->4)::text, '"%H%"', to_jsonb(mt.team_code)::text), '"%A%"', to_jsonb(mt.opponent)::text),
                                    '"@', '"de300000-0000-4000-8000-000000000')::jsonb AS pl0) a
 CROSS JOIN LATERAL (SELECT CASE WHEN e->>2 = 'innings_start'
                                 THEN a.pl0 || jsonb_build_object('squad', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name) ORDER BY x.o), '[]'::jsonb)
                FROM jsonb_array_elements(a.pl0->'squad') WITH ORDINALITY x(v, o) JOIN player p ON p.id = (x.v->>'id')::uuid), 'bowlingSquad', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name) ORDER BY x.o), '[]'::jsonb)
                FROM jsonb_array_elements(a.pl0->'bowlingSquad') WITH ORDINALITY x(v, o) JOIN player p ON p.id = (x.v->>'id')::uuid))
                                 WHEN a.pl0->>'fielder' LIKE '#%'
                                 THEN jsonb_set(a.pl0, '{fielder}', to_jsonb((SELECT p.full_name FROM player p
                                        WHERE p.id = ('de300000-0000-4000-8000-000000000' || substr(a.pl0->>'fielder', 2))::uuid)))
                                 ELSE a.pl0 END AS pl) b
 WHERE mt.id = current_setting('demo.m')::uuid
 ORDER BY (e->>0)::int;
SET LOCAL ROLE scrbrd_app;
DO $after$ DECLARE ids jsonb := current_setting('demo.ids')::jsonb; m uuid := nullif(current_setting('demo.m', true), '')::uuid;
        r record; d uuid; n integer; v uuid; t uuid;
BEGIN
  PERFORM app_session_begin((ids->>'scorer1.wes@example.invalid')::uuid, 'demo-season-pad-wes', NULL, NULL);
  SELECT x.ok, x.reason INTO r FROM match_finalise(m) x;
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The scorer could not finish 1xi-1007: %. Nothing was changed.', r.reason; END IF;

  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM fixture_publish(m, 'home', true);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'WES could not publish its side of 1xi-1007: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'dos.kea@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM fixture_publish(m, 'away', true);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'KEA could not publish its side of 1xi-1007: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'transport.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT tr.id INTO t FROM trip tr WHERE tr.match_id = m AND tr.cancelled_at IS NULL LIMIT 1;
  IF t IS NULL THEN
  INSERT INTO trip (match_id, school_id, vehicle_id, driver_id, depart_at, return_at, pickup, seats_taken, notes, arranged_by, arranged_at)
  SELECT m, match_school(m), (SELECT v.id FROM vehicle v WHERE v.school_id = '22222222-2222-2222-2222-222222222222' AND v.registration = 'WES DEMO 1'),
         (ids->>'driver.wes@example.invalid')::uuid, mt.starts_at - interval '75 minutes', mt.starts_at + interval '4 hours',
         'The junior school gate', 15, 'Demo season: the side to the ground and home.', app_user_id(), now()
    FROM match mt WHERE mt.id = m
  RETURNING id INTO t;
  IF t IS NULL THEN RAISE EXCEPTION 'The transport coordinator could not book the trip on 1xi-1007. Nothing was changed.'; END IF;
  END IF;
  PERFORM app_session_begin((ids->>'driver.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM trip_mark(t, 'departed');
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The driver could not mark the trip on 1xi-1007 departed: %. Nothing was changed.', r.reason; END IF;
  SELECT * INTO r FROM trip_mark(t, 'arrived');
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The driver could not mark the trip on 1xi-1007 arrived: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'league@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM match_conditions_refix_table(m, (SELECT cs.id FROM condition_set cs WHERE cs.competition_id = '99999999-0000-0000-0000-000000000001' AND cs.status = 'published' ORDER BY cs.version DESC LIMIT 1),
         'The league''s points for 2026, confirmed in its rules, applied to a fixture played before they were published.');
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The league could not re-fix the table figures of 1xi-1007: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'league@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT x.ok, x.reason INTO r FROM match_result_confirm(m) x;
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The result of 1xi-1007 could not be confirmed: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'pupil.wes.1xi@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT x.ok, x.reason, x.nomination_id AS id INTO r FROM captain_nominate(m, 'de300000-0000-4000-8000-000000000010', $d${"version":1,"basis":"batting_bowling","factsVersion":1,"headSeq":295,"suggestions":[{"playerId":"de300000-0000-4000-8000-000000000001","figures":"31 (16) · 4/19 (4)"},{"playerId":"de300000-0000-4000-8000-000000000010","figures":"10* (7) · 4/29 (4)"},{"playerId":"de300000-0000-4000-8000-000000000011","figures":"24 (19)"}],"nominee":{"playerId":"de300000-0000-4000-8000-000000000010","figures":"10* (7) · 4/29 (4)"}}$d$::jsonb) x;
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The captain could not nominate on 1xi-1007: %. Nothing was changed.', r.reason; END IF;
  v := r.id;
  PERFORM app_session_begin((ids->>'coach.wes.1xi@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM match_nomination_decide(v, 'confirm', NULL, $d${"version":1,"basis":"batting_bowling","factsVersion":1,"headSeq":295,"suggestions":[{"playerId":"de300000-0000-4000-8000-000000000001","figures":"31 (16) · 4/19 (4)"},{"playerId":"de300000-0000-4000-8000-000000000010","figures":"10* (7) · 4/29 (4)"},{"playerId":"de300000-0000-4000-8000-000000000011","figures":"24 (19)"}],"awardee":{"playerId":"de300000-0000-4000-8000-000000000010","figures":"10* (7) · 4/29 (4)"}}$d$::jsonb);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The coach could not confirm the captain''s nomination on 1xi-1007: %. Nothing was changed.', r.reason; END IF;
END $after$;
RESET ROLE;
DO $verified$ BEGIN
  IF NOT match_verified(current_setting('demo.m')::uuid) THEN RAISE EXCEPTION '1xi-1007 is finished but not verified. Nothing was changed.'; END IF;
END $verified$;

