    VALUES (m, match_school(m), 'umpire', 'WES Umpire (demo)', (ids->>'official.wes@example.invalid')::uuid, NULL, NULL, app_user_id(), now())
    RETURNING id INTO d;
    IF d IS NULL THEN RAISE EXCEPTION 'Could not appoint the umpire on 2xi-1010. Nothing was changed.'; END IF;
  PERFORM app_session_begin((ids->>'registrar.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    SELECT * INTO r FROM duty_link(d);
    IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The office could not link the umpire duty on 2xi-1010: %. Nothing was changed.', r.reason; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM match_official o WHERE o.match_id = m AND o.duty = 'umpire' AND NOT o.withdrawn
                   AND (o.official_id = '0a000000-0000-0000-0000-000000000004' OR 'umpire' IN ('scorer', 'third_umpire', 'referee'))) THEN
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    INSERT INTO match_official (match_id, school_id, duty, person_name, person_id, official_id, panel, appointed_by, appointed_at)
    VALUES (m, match_school(m), 'umpire', 'T Sithole', NULL, '0a000000-0000-0000-0000-000000000004', 'KZN school umpires (demo)', app_user_id(), now())
    RETURNING id INTO d;
    IF d IS NULL THEN RAISE EXCEPTION 'Could not appoint the umpire on 2xi-1010. Nothing was changed.'; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM match_official o WHERE o.match_id = m AND o.duty = 'third_umpire' AND NOT o.withdrawn
                   AND (o.official_id = '0a000000-0000-0000-0000-000000000005' OR 'third_umpire' IN ('scorer', 'third_umpire', 'referee'))) THEN
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    INSERT INTO match_official (match_id, school_id, duty, person_name, person_id, official_id, panel, appointed_by, appointed_at)
    VALUES (m, match_school(m), 'third_umpire', 'V Ngcobo', NULL, '0a000000-0000-0000-0000-000000000005', 'KZN school umpires (demo)', app_user_id(), now())
    RETURNING id INTO d;
    IF d IS NULL THEN RAISE EXCEPTION 'Could not appoint the third_umpire on 2xi-1010. Nothing was changed.'; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM match_official o WHERE o.match_id = m AND o.duty = 'referee' AND NOT o.withdrawn
                   AND (o.official_id = '0a000000-0000-0000-0000-000000000003' OR 'referee' IN ('scorer', 'third_umpire', 'referee'))) THEN
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    INSERT INTO match_official (match_id, school_id, duty, person_name, person_id, official_id, panel, appointed_by, appointed_at)
    VALUES (m, match_school(m), 'referee', 'G Marais', NULL, '0a000000-0000-0000-0000-000000000003', 'Match referee (demo)', app_user_id(), now())
    RETURNING id INTO d;
    IF d IS NULL THEN RAISE EXCEPTION 'Could not appoint the referee on 2xi-1010. Nothing was changed.'; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM match_official o WHERE o.match_id = m AND o.duty = 'scorer' AND NOT o.withdrawn
                   AND (o.person_id = (ids->>'scorer1.wes@example.invalid')::uuid OR 'scorer' IN ('scorer', 'third_umpire', 'referee'))) THEN
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    INSERT INTO match_official (match_id, school_id, duty, person_name, person_id, official_id, panel, appointed_by, appointed_at)
    VALUES (m, match_school(m), 'scorer', 'WES Scorer One (demo)', (ids->>'scorer1.wes@example.invalid')::uuid, NULL, NULL, app_user_id(), now())
    RETURNING id INTO d;
    IF d IS NULL THEN RAISE EXCEPTION 'Could not appoint the scorer on 2xi-1010. Nothing was changed.'; END IF;
  PERFORM app_session_begin((ids->>'registrar.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    SELECT * INTO r FROM duty_link(d);
    IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The office could not link the scorer duty on 2xi-1010: %. Nothing was changed.', r.reason; END IF;
  END IF;
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  INSERT INTO match_pitch_report (match_id, school_id, surface, grass, bounce, pace, favours, covers_on, notes, bounce_rating, pace_rating, outfield, reported_by, reported_at)
  VALUES (m, match_school(m), 'firm', 'covered', 'even', 'medium', 'even', false, 'Covered overnight. Expected to turn a little later.', 5, 5, 'medium', app_user_id(), now())
  ON CONFLICT (match_id) DO NOTHING;
  INSERT INTO match_weather (match_id, condition, temp_c, humidity_pct, wind_kph, wind_dir, uv_index, rain_chance_pct, forecast, playable, observed_at)
  VALUES (m, 'Hot and humid', 31, 78, 8, 'N', 11, 10, 'Demo forecast: settled through the afternoon.', true, now())
  ON CONFLICT (match_id) DO NOTHING;
  IF (SELECT count(*) FROM match_squad q WHERE q.match_id = m AND q.side = 'home' AND NOT q.withdrawn) < 11 THEN
  PERFORM app_session_begin((ids->>'coach.wes.2xi@example.invalid')::uuid, 'demo-season', NULL, NULL);
    SELECT count(*) INTO n FROM match mt CROSS JOIN unnest(ARRAY['de300000-0000-4000-8000-000000000016', 'de300000-0000-4000-8000-000000000022', 'de300000-0000-4000-8000-000000000023', 'de300000-0000-4000-8000-000000000024', 'de300000-0000-4000-8000-000000000025', 'de300000-0000-4000-8000-000000000017', 'de300000-0000-4000-8000-000000000019', 'de300000-0000-4000-8000-000000000020', 'de300000-0000-4000-8000-000000000021', 'de300000-0000-4000-8000-000000000018', 'de300000-0000-4000-8000-000000000026']::uuid[]) p(id) JOIN player pl ON pl.id = p.id
     WHERE mt.id = m AND pl.school_id = mt.school_id
       AND app_can('team.select', pl.school_id, mt.team_code, p.id, mt.id);
