full"],[296,1,"ball",13191,{"bowlerApproach":null,"fielder":null,"dismissed":null,"freeHit":false,"id":"ds-2xi-1010-1-144"},"run",6,"loft",6,"boundary","016","019","190",null,null,177,1,"point",null,"full"],[297,1,"innings_end",13221,{"reason":"target_reached","confirmed":{"runs":169,"wickets":5,"balls":114},"id":"ds-2xi-1010-1-seal"}]]$ev$::jsonb) e
 CROSS JOIN LATERAL (SELECT replace(replace(replace((e->4)::text, '"%H%"', to_jsonb(mt.team_code)::text), '"%A%"', to_jsonb(mt.opponent)::text),
                                    '"@', '"de300000-0000-4000-8000-000000000')::jsonb AS pl0) a
 CROSS JOIN LATERAL (SELECT CASE WHEN e->>2 = 'innings_start'
                                 THEN a.pl0 || jsonb_build_object('squad', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name) ORDER BY x.o), '[]'::jsonb)
                FROM jsonb_array_elements(a.pl0->'squad') WITH ORDINALITY x(v, o) JOIN player p ON p.id = (x.v->>'id')::uuid), 'bowlingSquad', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name) ORDER BY x.o), '[]'::jsonb)
                FROM jsonb_array_elements(a.pl0->'bowlingSquad') WITH ORDINALITY x(v, o) JOIN player p ON p.id = (x.v->>'id')::uuid))
                                 WHEN a.pl0->>'fielder' LIKE '#%'
                                 THEN jsonb_set(a.pl0, '{fielder}', to_jsonb((SELECT p.full_name FROM player p
                                        WHERE p.id = ('de300000-0000-4000-8000-000000000' || substr(a.pl0->>'fielder', 2))::uuid)))
                                 ELSE a.pl0 END AS pl) b
 WHERE mt.id = current_setting('demo.m')::uuid
 ORDER BY (e->>0)::int;
SET LOCAL ROLE scrbrd_app;
DO $after$ DECLARE ids jsonb := current_setting('demo.ids')::jsonb; m uuid := nullif(current_setting('demo.m', true), '')::uuid;
        r record; d uuid; n integer; v uuid; t uuid;
BEGIN
  PERFORM app_session_begin((ids->>'scorer1.wes@example.invalid')::uuid, 'demo-season-pad-wes', NULL, NULL);
  SELECT x.ok, x.reason INTO r FROM match_finalise(m) x;
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The scorer could not finish 2xi-1010: %. Nothing was changed.', r.reason; END IF;

  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM fixture_publish(m, 'home', true);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'WES could not publish its side of 2xi-1010: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'dos.kea@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM fixture_publish(m, 'away', true);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'KEA could not publish its side of 2xi-1010: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'transport.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT tr.id INTO t FROM trip tr WHERE tr.match_id = m AND tr.cancelled_at IS NULL LIMIT 1;
  IF t IS NULL THEN
  INSERT INTO trip (match_id, school_id, vehicle_id, driver_id, depart_at, return_at, pickup, seats_taken, notes, arranged_by, arranged_at)
  SELECT m, match_school(m), (SELECT v.id FROM vehicle v WHERE v.school_id = '22222222-2222-2222-2222-222222222222' AND v.registration = 'WES DEMO 1'),
         (ids->>'driver.wes@example.invalid')::uuid, mt.starts_at - interval '75 minutes', mt.starts_at + interval '4 hours',
         'The junior school gate', 15, 'Demo season: the side to the ground and home.', app_user_id(), now()
    FROM match mt WHERE mt.id = m
  RETURNING id INTO t;
  IF t IS NULL THEN RAISE EXCEPTION 'The transport coordinator could not book the trip on 2xi-1010. Nothing was changed.'; END IF;
  END IF;
  PERFORM app_session_begin((ids->>'driver.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM trip_mark(t, 'departed');
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The driver could not mark the trip on 2xi-1010 departed: %. Nothing was changed.', r.reason; END IF;
  SELECT * INTO r FROM trip_mark(t, 'arrived');
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The driver could not mark the trip on 2xi-1010 arrived: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT x.ok, x.reason INTO r FROM match_result_confirm(m) x;
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The result of 2xi-1010 could not be confirmed: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'coach.wes.2xi@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM match_award(m, 'de300000-0000-4000-8000-000000000016', $d${"version":1,"basis":"batting_bowling","factsVersion":1,"headSeq":297,"suggestions":[{"playerId":"de300000-0000-4000-8000-000000000016","figures":"94* (63)"},{"playerId":"de300000-0000-4000-8000-000000000018","figures":"2/28 (4)"},{"playerId":"de300000-0000-4000-8000-000000000019","figures":"7* (4) · 1/30 (4)"}],"awardee":{"playerId":"de300000-0000-4000-8000-000000000016","figures":"94* (63)"}}$d$::jsonb);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The WES coach could not award Player of the Match on 2xi-1010: %. Nothing was changed.', r.reason; END IF;
END $after$;
RESET ROLE;
DO $verified$ BEGIN
  IF NOT match_verified(current_setting('demo.m')::uuid) THEN RAISE EXCEPTION '2xi-1010 is finished but not verified. Nothing was changed.'; END IF;
END $verified$;

-- ── 3xi-1010: Westville v Kearsney at Westville Main · WES 175/2, KEA 178/3: KEA won ──
RESET ROLE;
SELECT set_config('demo.m', (SELECT id FROM match WHERE school_id = '22222222-2222-2222-2222-222222222222' AND away_school_id = '33333333-3333-3333-3333-333333333333'
   AND team_code = '3XI' AND starts_at = timestamptz '2026-10-10T12:00:00Z')::text, true);
DO $chk$ BEGIN IF nullif(current_setting('demo.m', true), '') IS NULL THEN
  RAISE EXCEPTION 'The demo''s 3XI fixture of 2026-10-10T12:00:00Z is not here. Nothing was changed.'; END IF; END $chk$;
SET LOCAL ROLE scrbrd_app;
DO $before$ DECLARE ids jsonb := current_setting('demo.ids')::jsonb; m uuid := nullif(current_setting('demo.m', true), '')::uuid;
        r record; d uuid; n integer; v uuid; t uuid;
BEGIN


  IF NOT EXISTS (SELECT 1 FROM match_official o WHERE o.match_id = m AND o.duty = 'umpire' AND NOT o.withdrawn
                   AND (o.person_id = (ids->>'official.wes@example.invalid')::uuid OR 'umpire' IN ('scorer', 'third_umpire', 'referee'))) THEN
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    INSERT INTO match_official (match_id, school_id, duty, person_name, person_id, official_id, panel, appointed_by, appointed_at)
    VALUES (m, match_school(m), 'umpire', 'WES Umpire (demo)', (ids->>'official.wes@example.invalid')::uuid, NULL, NULL, app_user_id(), now())
    RETURNING id INTO d;
    IF d IS NULL THEN RAISE EXCEPTION 'Could not appoint the umpire on 3xi-1010. Nothing was changed.'; END IF;
  PERFORM app_session_begin((ids->>'registrar.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    SELECT * INTO r FROM duty_link(d);
    IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The office could not link the umpire duty on 3xi-1010: %. Nothing was changed.', r.reason; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM match_official o WHERE o.match_id = m AND o.duty = 'umpire' AND NOT o.withdrawn
                   AND (o.official_id = '0a000000-0000-0000-0000-000000000005' OR 'umpire' IN ('scorer', 'third_umpire', 'referee'))) THEN
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    INSERT INTO match_official (match_id, school_id, duty, person_name, person_id, official_id, panel, appointed_by, appointed_at)
    VALUES (m, match_school(m), 'umpire', 'V Ngcobo', NULL, '0a000000-0000-0000-0000-000000000005', 'KZN school umpires (demo)', app_user_id(), now())
    RETURNING id INTO d;
    IF d IS NULL THEN RAISE EXCEPTION 'Could not appoint the umpire on 3xi-1010. Nothing was changed.'; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM match_official o WHERE o.match_id = m AND o.duty = 'third_umpire' AND NOT o.withdrawn
                   AND (o.official_id = '0a000000-0000-0000-0000-000000000001' OR 'third_umpire' IN ('scorer', 'third_umpire', 'referee'))) THEN
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    INSERT INTO match_official (match_id, school_id, duty, person_name, person_id, official_id, panel, appointed_by, appointed_at)
    VALUES (m, match_school(m), 'third_umpire', 'E Ndlovu', NULL, '0a000000-0000-0000-0000-000000000001', 'KZN school umpires (demo)', app_user_id(), now())
    RETURNING id INTO d;
    IF d IS NULL THEN RAISE EXCEPTION 'Could not appoint the third_umpire on 3xi-1010. Nothing was changed.'; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM match_official o WHERE o.match_id = m AND o.duty = 'referee' AND NOT o.withdrawn
                   AND (o.official_id = '0a000000-0000-0000-0000-000000000003' OR 'referee' IN ('scorer', 'third_umpire', 'referee'))) THEN
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    INSERT INTO match_official (match_id, school_id, duty, person_name, person_id, official_id, panel, appointed_by, appointed_at)
    VALUES (m, match_school(m), 'referee', 'G Marais', NULL, '0a000000-0000-0000-0000-000000000003', 'Match referee (demo)', app_user_id(), now())
    RETURNING id INTO d;
    IF d IS NULL THEN RAISE EXCEPTION 'Could not appoint the referee on 3xi-1010. Nothing was changed.'; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM match_official o WHERE o.match_id = m AND o.duty = 'scorer' AND NOT o.withdrawn
                   AND (o.person_id = (ids->>'scorer1.wes@example.invalid')::uuid OR 'scorer' IN ('scorer', 'third_umpire', 'referee'))) THEN
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    INSERT INTO match_official (match_id, school_id, duty, person_name, person_id, official_id, panel, appointed_by, appointed_at)
    VALUES (m, match_school(m), 'scorer', 'WES Scorer One (demo)', (ids->>'scorer1.wes@example.invalid')::uuid, NULL, NULL, app_user_id(), now())
    RETURNING id INTO d;
    IF d IS NULL THEN RAISE EXCEPTION 'Could not appoint the scorer on 3xi-1010. Nothing was changed.'; END IF;
  PERFORM app_session_begin((ids->>'registrar.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
    SELECT * INTO r FROM duty_link(d);
    IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The office could not link the scorer duty on 3xi-1010: %. Nothing was changed.', r.reason; END IF;
  END IF;
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  INSERT INTO match_pitch_report (match_id, school_id, surface, grass, bounce, pace, favours, covers_on, notes, bounce_rating, pace_rating, outfield, reported_by, reported_at)
  VALUES (m, match_school(m), 'soft', 'green', 'low', 'slow', 'spin', false, 'Rain on Tuesday; outfield heavy. Ball stopping on the batters.', 4, 3, 'slow', app_user_id(), now())
  ON CONFLICT (match_id) DO NOTHING;
  INSERT INTO match_weather (match_id, condition, temp_c, humidity_pct, wind_kph, wind_dir, uv_index, rain_chance_pct, forecast, playable, observed_at)
  VALUES (m, 'Overcast, mild', 21, 72, 15, 'SW', 4, 35, 'Demo forecast: settled through the afternoon.', true, now())
  ON CONFLICT (match_id) DO NOTHING;
  IF (SELECT count(*) FROM match_squad q WHERE q.match_id = m AND q.side = 'home' AND NOT q.withdrawn) < 11 THEN
  PERFORM app_session_begin((ids->>'coach.wes.3xi@example.invalid')::uuid, 'demo-season', NULL, NULL);
    SELECT count(*) INTO n FROM match mt CROSS JOIN unnest(ARRAY['de300000-0000-4000-8000-000000000033', 'de300000-0000-4000-8000-000000000034', 'de300000-0000-4000-8000-000000000037', 'de300000-0000-4000-8000-000000000038', 'de300000-0000-4000-8000-000000000040', 'de300000-0000-4000-8000-000000000039', 'de300000-0000-4000-8000-000000000031', 'de300000-0000-4000-8000-000000000032', 'de300000-0000-4000-8000-000000000036', 'de300000-0000-4000-8000-000000000035', 'de300000-0000-4000-8000-000000000041']::uuid[]) p(id) JOIN player pl ON pl.id = p.id
     WHERE mt.id = m AND pl.school_id = mt.school_id
       AND app_can('team.select', pl.school_id, mt.team_code, p.id, mt.id);
    IF n <> 11 THEN RAISE EXCEPTION 'WES 3XI coach may not name his XI for 3xi-1010 (% of 11). Nothing was changed.', n; END IF;
    UPDATE match_squad SET withdrawn = true WHERE match_id = m AND side = 'home' AND NOT withdrawn;
    INSERT INTO match_squad (match_id, player_id, side, batting_no, twelfth, withdrawn, selected_by, selected_at)
    SELECT m, p.id, 'home', p.o, false, false, app_user_id(), now() FROM unnest(ARRAY['de300000-0000-4000-8000-000000000033', 'de300000-0000-4000-8000-000000000034', 'de300000-0000-4000-8000-000000000037', 'de300000-0000-4000-8000-000000000038', 'de300000-0000-4000-8000-000000000040', 'de300000-0000-4000-8000-000000000039', 'de300000-0000-4000-8000-000000000031', 'de300000-0000-4000-8000-000000000032', 'de300000-0000-4000-8000-000000000036', 'de300000-0000-4000-8000-000000000035', 'de300000-0000-4000-8000-000000000041']::uuid[]) WITH ORDINALITY p(id, o)
    ON CONFLICT (match_id, player_id) DO UPDATE SET side = excluded.side, batting_no = excluded.batting_no, twelfth = false,
       withdrawn = false, selected_by = excluded.selected_by, selected_at = excluded.selected_at;
  END IF;
