361,{"bowlerApproach":null,"fielder":null,"dismissed":null,"freeHit":false,"id":"ds-3xi-1010-1-126"},"run",0,"fwd_def",null,null,"200","209","035"],[282,1,"ball",12399,{"bowlerApproach":null,"fielder":null,"dismissed":null,"freeHit":false,"id":"ds-3xi-1010-1-127"},"run",1,"drive",8,"outer","200","209","035",null,null,245,0.52,"point",null,"full"],[283,1,"ball",12437,{"bowlerApproach":null,"fielder":null,"dismissed":null,"freeHit":false,"id":"ds-3xi-1010-1-128"},"run",4,"loft",7,"boundary","209","200","035",null,null,157,1,"point",null,"full"],[284,1,"ball",12475,{"bowlerApproach":null,"fielder":null,"dismissed":null,"freeHit":false,"id":"ds-3xi-1010-1-129"},"run",6,"loft",null,null,"209","200","035"],[285,1,"innings_end",12505,{"reason":"target_reached","confirmed":{"runs":178,"wickets":3,"balls":102},"id":"ds-3xi-1010-1-seal"}]]$ev$::jsonb) e
 CROSS JOIN LATERAL (SELECT replace(replace(replace((e->4)::text, '"%H%"', to_jsonb(mt.team_code)::text), '"%A%"', to_jsonb(mt.opponent)::text),
                                    '"@', '"de300000-0000-4000-8000-000000000')::jsonb AS pl0) a
 CROSS JOIN LATERAL (SELECT CASE WHEN e->>2 = 'innings_start'
                                 THEN a.pl0 || jsonb_build_object('squad', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name) ORDER BY x.o), '[]'::jsonb)
                FROM jsonb_array_elements(a.pl0->'squad') WITH ORDINALITY x(v, o) JOIN player p ON p.id = (x.v->>'id')::uuid), 'bowlingSquad', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name) ORDER BY x.o), '[]'::jsonb)
                FROM jsonb_array_elements(a.pl0->'bowlingSquad') WITH ORDINALITY x(v, o) JOIN player p ON p.id = (x.v->>'id')::uuid))
                                 WHEN a.pl0->>'fielder' LIKE '#%'
                                 THEN jsonb_set(a.pl0, '{fielder}', to_jsonb((SELECT p.full_name FROM player p
                                        WHERE p.id = ('de300000-0000-4000-8000-000000000' || substr(a.pl0->>'fielder', 2))::uuid)))
                                 ELSE a.pl0 END AS pl) b
 WHERE mt.id = current_setting('demo.m')::uuid
 ORDER BY (e->>0)::int;
SET LOCAL ROLE scrbrd_app;
DO $after$ DECLARE ids jsonb := current_setting('demo.ids')::jsonb; m uuid := nullif(current_setting('demo.m', true), '')::uuid;
        r record; d uuid; n integer; v uuid; t uuid;
BEGIN
  PERFORM app_session_begin((ids->>'scorer1.wes@example.invalid')::uuid, 'demo-season-pad-wes', NULL, NULL);
  SELECT x.ok, x.reason INTO r FROM match_finalise(m) x;
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The scorer could not finish 3xi-1010: %. Nothing was changed.', r.reason; END IF;

  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM fixture_publish(m, 'home', true);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'WES could not publish its side of 3xi-1010: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'dos.kea@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM fixture_publish(m, 'away', true);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'KEA could not publish its side of 3xi-1010: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'transport.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT tr.id INTO t FROM trip tr WHERE tr.match_id = m AND tr.cancelled_at IS NULL LIMIT 1;
  IF t IS NULL THEN
  INSERT INTO trip (match_id, school_id, vehicle_id, driver_id, depart_at, return_at, pickup, seats_taken, notes, arranged_by, arranged_at)
  SELECT m, match_school(m), (SELECT v.id FROM vehicle v WHERE v.school_id = '22222222-2222-2222-2222-222222222222' AND v.registration = 'WES DEMO 1'),
         (ids->>'driver.wes@example.invalid')::uuid, mt.starts_at - interval '75 minutes', mt.starts_at + interval '4 hours',
         'The junior school gate', 15, 'Demo season: the side to the ground and home.', app_user_id(), now()
    FROM match mt WHERE mt.id = m
  RETURNING id INTO t;
  IF t IS NULL THEN RAISE EXCEPTION 'The transport coordinator could not book the trip on 3xi-1010. Nothing was changed.'; END IF;
  END IF;
  PERFORM app_session_begin((ids->>'driver.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM trip_mark(t, 'departed');
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The driver could not mark the trip on 3xi-1010 departed: %. Nothing was changed.', r.reason; END IF;
  SELECT * INTO r FROM trip_mark(t, 'arrived');
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The driver could not mark the trip on 3xi-1010 arrived: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'dos.wes@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT x.ok, x.reason INTO r FROM match_result_confirm(m) x;
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The result of 3xi-1010 could not be confirmed: %. Nothing was changed.', r.reason; END IF;
  PERFORM app_session_begin((ids->>'coach.wes.3xi@example.invalid')::uuid, 'demo-season', NULL, NULL);
  SELECT * INTO r FROM match_award(m, 'de300000-0000-4000-8000-000000000034', $d${"version":1,"basis":"batting_bowling","factsVersion":1,"headSeq":285,"suggestions":[{"playerId":"de300000-0000-4000-8000-000000000034","figures":"90* (55)"},{"playerId":"de300000-0000-4000-8000-000000000037","figures":"47 (44)"},{"playerId":"de300000-0000-4000-8000-000000000035","figures":"2/35 (4)"}],"awardee":{"playerId":"de300000-0000-4000-8000-000000000034","figures":"90* (55)"}}$d$::jsonb);
  IF NOT coalesce(r.ok, false) THEN RAISE EXCEPTION 'The WES coach could not award Player of the Match on 3xi-1010: %. Nothing was changed.', r.reason; END IF;
END $after$;
RESET ROLE;
DO $verified$ BEGIN
  IF NOT match_verified(current_setting('demo.m')::uuid) THEN RAISE EXCEPTION '3xi-1010 is finished but not verified. Nothing was changed.'; END IF;
END $verified$;

RESET ROLE;
DO $check$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM ball_event WHERE idempotency_key = 'ds-1xi-1007-0-1') THEN
    RAISE EXCEPTION 'The demo season is incomplete (1xi-1007). Rolled back.'; END IF;
  IF NOT EXISTS (SELECT 1 FROM ball_event WHERE idempotency_key = 'ds-u16a-1008-0-1') THEN
    RAISE EXCEPTION 'The demo season is incomplete (u16a-1008). Rolled back.'; END IF;
  IF NOT EXISTS (SELECT 1 FROM ball_event WHERE idempotency_key = 'ds-2xi-1010-0-1') THEN
    RAISE EXCEPTION 'The demo season is incomplete (2xi-1010). Rolled back.'; END IF;
  IF NOT EXISTS (SELECT 1 FROM ball_event WHERE idempotency_key = 'ds-3xi-1010-0-1') THEN
    RAISE EXCEPTION 'The demo season is incomplete (3xi-1010). Rolled back.'; END IF;
END $check$;
COMMIT;
